'use strict';

function flattenConfig(input) {
  if (!isPlainObject(input)) throw new TypeError('input must be a plain object');
  const entries = [];
  const active = new WeakSet();

  function cloneValue(value) {
    if (value === null || typeof value === 'string' || typeof value === 'boolean') return value;
    if (typeof value === 'number') {
      if (!Number.isFinite(value)) throw new TypeError('numbers must be finite');
      return value;
    }
    if (typeof value !== 'object') throw new TypeError('unsupported value');
    if (Array.isArray(value)) return value.slice();
    if (active.has(value)) throw new RangeError('cyclic value');
    active.add(value);
    let copy;
    if (isPlainObject(value)) {
      copy = {};
      for (const key of Object.keys(value)) copy[key] = cloneValue(value[key]);
    } else {
      active.delete(value);
      throw new TypeError('unsupported object');
    }
    active.delete(value);
    return copy;
  }

  function visit(object, path) {
    if (active.has(object)) throw new RangeError('cyclic value');
    active.add(object);
    for (const key of Object.keys(object).sort()) {
      const value = object[key];
      if (isPlainObject(value) && Object.keys(value).length > 0) {
        visit(value, path.concat(key));
      } else {
        entries.push({ path: path.concat(key), value: cloneValue(value) });
      }
    }
    active.delete(object);
  }

  visit(input, []);
  return entries;
}

function isPlainObject(value) {
  return value !== null &&
    typeof value === 'object' &&
    Object.getPrototypeOf(value) === Object.prototype;
}

module.exports = { flattenConfig };

