'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['flattenConfig']);
const { flattenConfig } = api;

const arrayLeaf = [1, { z: ['x', { ok: true }] }, null];
const input = {
  z: 'last',
  a: { d: 4, b: false, c: {} },
  m: arrayLeaf,
  n: null
};
const before = structuredClone(input);
const result = flattenConfig(input);
assert.deepEqual(result, [
  { path: ['a', 'b'], value: false },
  { path: ['a', 'c'], value: {} },
  { path: ['a', 'd'], value: 4 },
  { path: ['m'], value: [1, { z: ['x', { ok: true }] }, null] },
  { path: ['n'], value: null },
  { path: ['z'], value: 'last' }
]);
assert.deepEqual(input, before);
assert.notStrictEqual(result[2].path, result[1].path);
assert.notStrictEqual(result[1].value, input.a.c);
assert.notStrictEqual(result[3].value, arrayLeaf);
assert.notStrictEqual(result[3].value[1], arrayLeaf[1]);
assert.notStrictEqual(result[3].value[1].z, arrayLeaf[1].z);
assert.notStrictEqual(result[3].value[1].z[1], arrayLeaf[1].z[1]);

assert.deepEqual(flattenConfig({}), []);
assert.deepEqual(flattenConfig({ emptyArray: [], emptyObject: {} }), [
  { path: ['emptyArray'], value: [] },
  { path: ['emptyObject'], value: {} }
]);

const shared = [{ deep: { value: 1 } }];
const sharedResult = flattenConfig({ a: shared, b: shared });
assert.deepEqual(sharedResult, [
  { path: ['a'], value: [{ deep: { value: 1 } }] },
  { path: ['b'], value: [{ deep: { value: 1 } }] }
]);
assert.notStrictEqual(sharedResult[0].value, sharedResult[1].value);
assert.notStrictEqual(sharedResult[0].value[0], sharedResult[1].value[0]);
assert.notStrictEqual(sharedResult[0].value[0].deep, sharedResult[1].value[0].deep);

const first = flattenConfig({ a: [1] });
const second = flattenConfig({ a: [1] });
assert.notStrictEqual(first, second);
assert.notStrictEqual(first[0], second[0]);
assert.notStrictEqual(first[0].path, second[0].path);
assert.notStrictEqual(first[0].value, second[0].value);

for (const bad of [null, [], 'x', 1, new Date(), Object.create(null)]) {
  assert.throws(() => flattenConfig(bad), TypeError);
}
for (const badValue of [undefined, Infinity, -Infinity, NaN, function () {}, Symbol('x'), 1n, new Date()]) {
  assert.throws(() => flattenConfig({ bad: badValue }), TypeError);
}
const sparse = [];
sparse[1] = 'x';
assert.throws(() => flattenConfig({ sparse }), TypeError);
const objectCycle = {};
objectCycle.self = objectCycle;
assert.throws(() => flattenConfig(objectCycle), RangeError);
const arrayCycle = [];
arrayCycle.push(arrayCycle);
assert.throws(() => flattenConfig({ arrayCycle }), RangeError);

